Lemma tr_pro1 : forall (sp cp L pp plen : Z)
    (ra gp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) F fc (m : word -> option byte) (lo : Z),
  stk asegs m lo sp -> SEGTOP_A <= lo -> lo + 0x1000 <= sp -> sp mod 16 = 0 -> sp < 2^47 -> mem_inv asegs m ->
  evt asegs (fun ms' => exists (a1' : word) (m' : word -> option byte),
                 ms' = entry_st ra (Z_to_bv 64 (sp - 80)) gp (Z_to_bv 64 TP_A) t0 t1 t2 (Z_to_bv 64 plen) (Z_to_bv 64 pp)
                          (Z_to_bv 64 cp) a1' (Z_to_bv 64 pp) (Z_to_bv 64 plen) a4 a5 a6 a7 (Z_to_bv 64 L) s3
                          (Z_to_bv 64 TR_INIT) s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc 0xf9e20 m'
       /\ munch [(sp - 80, sp)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'
       /\ tr_frame m' sp ra s0 s1 s2 s3 s4 s5 s6 s7 /\ stk asegs m' lo (sp - 80))
    (entry_st ra (Z_to_bv 64 sp) gp (Z_to_bv 64 TP_A) t0 t1 t2 s0 s1 (Z_to_bv 64 cp) (Z_to_bv 64 L) (Z_to_bv 64 pp) (Z_to_bv 64 plen)
       a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc e_target_run m).
