Lemma tr_pro2_empty : forall (sp cp L pp : Z) (c0 : byte)
    (ra gp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) F fc (m : word -> option byte),
  0 < cp < 2^47 -> 0 <= L < 32768 -> (SEGTOP_A <= cp \/ cp + 1 <= 0x10000) ->
  (0 < L -> bytes_at asegs m cp [c0]) -> mem_inv asegs m ->
  evt asegs (fun ms' => exists (a0' : word),
                 ms' = entry_st ra (Z_to_bv 64 sp) gp (Z_to_bv 64 TP_A) t0 t1 t2 (Z_to_bv 64 0) (Z_to_bv 64 TR_EMPTY)
                          a0' a1 a2 a3 a4 a5 a6 a7 (Z_to_bv 64 0) (Z_to_bv 64 cp) (Z_to_bv 64 TR_INIT)
                          (Z_to_bv 64 (tr_calls L c0)) (Z_to_bv 64 0) (Z_to_bv 64 TR_M2) s8 s9 s10 s11 t3 t4 t5 t6 F fc 0xf9ea0 m)
    (entry_st ra (Z_to_bv 64 sp) gp (Z_to_bv 64 TP_A) t0 t1 t2 (Z_to_bv 64 0) (Z_to_bv 64 pp) a0 a1 a2 a3 a4 a5 a6 a7
       (Z_to_bv 64 L) (Z_to_bv 64 cp) (Z_to_bv 64 TR_INIT) s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc 0xf9e2c m).
Proof.
